#!/bin/bash
# Install the pre-push hook as a shim that runs the tracked scripts/hooks/pre-push,
# so edits to the hook take effect without reinstalling (pattern from regenstudio-website).
set -euo pipefail
cd "$(dirname "$0")/../.."

cat > .git/hooks/pre-push <<'SHIM'
#!/bin/bash
# Generated by scripts/hooks/install.sh: do not edit, edit scripts/hooks/pre-push.
set -euo pipefail
src="$(git rev-parse --show-toplevel)/scripts/hooks/pre-push"
if [ ! -x "$src" ]; then
  echo "pre-push: $src is missing or not executable; refusing to push unchecked" >&2
  exit 1
fi
exec "$src" "$@"
SHIM

chmod +x .git/hooks/pre-push
echo "Installed .git/hooks/pre-push (shim to scripts/hooks/pre-push)"
